with recent_store_sales as (select *, date_add(sale_date, 44) as sale_date_plus_44d from store_sales where month(sale_date) in (6, 7, 10) and units between 38 and 39), StoreIdSummary as (select store_id, month(sale_date_plus_44d) as sale_plus_44d_month, max(sale_date_plus_44d) as latest_sale_date_plus_44d, max(revenue) - min(revenue) as revenue_range from recent_store_sales group by store_id, month(sale_date_plus_44d)) select store_id, sale_plus_44d_month, latest_sale_date_plus_44d, revenue_range from StoreIdSummary order by store_id asc, sale_plus_44d_month asc limit 1;
